package com.ggiova.gallery.data;

/**
 * Represents one item, as in, an image or video.
 *
 * @param id          Unique autogenerated long identification.
 * @param hash        of the file.
 * @param storagePath relative path of where the file can be found.
 * @param mime        label for the type of file, following the "[category]/[format]" structure. For example: "image/png" or "video/mp4".
 * @param sizeBytes   Non-nullable size in bytes.
 * @param width       Non-nullable width of the file.
 * @param height      Non-nullable height of the file.
 * @param durationMs  Nullable, for videos only.
 * @param title       of the file.
 * @param description of the file.
 * @param isFavorite  determines if the file is favorite.
 */
public record Item(
        long id,                     // non-nullable
        String hash,
        String storagePath,
        String mime,
        long sizeBytes,              // non-nullable
        int width,                   // non-nullable
        int height,                  // non-nullable
        Long durationMs,
        String title,
        String description,
        boolean isFavorite
) {}
